def build_battery(
    *,
    AI: BatteryAI | dict[str, Any] | None = None,
    AO: BatteryAO | dict[str, Any] | None = None,
    BI: BatteryBI | dict[str, Any] | None = None,
) -> Battery:
    """Build the 'Battery equipment block' group from its per-type point groups."""
    return Battery(
        AI=AI,
        AO=AO,
        BI=BI,
    )


